import json
N=30
g=[[0]*N for _ in range(N)]
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for tr, y0 in enumerate([1,8,15,22,29]):
  for tc,x0 in enumerate([1,8,15,22,29]):
    for dy in range(5):
      for dx in range(5):
        y,x=y0+dy,x0+dx
        if y<N and x<N:
          g[y][x]=4 if dy in (0,4) or dx in (0,4) else colors[tr][tc]
# Connect the corner blocks for colors 3 and 8, filling only blank separator gaps.
# Color 3 corners tile rows 0,2 and cols 0,3.
for color, trs, tcs in [(3,[0,2],[0,3]),(8,[1,3],[1,2])]:
  ys=[2+7*t for t in trs]; xs=[2+7*t for t in tcs]
  # connect horizontal pair across separators, over each block's interior row
  for y in range(ys[0],ys[0]+3):
    for x in range(xs[0]+3,xs[1]-2):
      if g[y][x]==0: g[y][x]=color
  # connect vertical pair across separators, over each block's interior column
  for x in range(xs[0],xs[0]+3):
    for y in range(ys[0]+3,ys[1]-2):
      if g[y][x]==0: g[y][x]=color
  for x in range(xs[1],xs[1]+3):
    for y in range(ys[0]+3,ys[1]-2):
      if g[y][x]==0: g[y][x]=color
  # right-side horizontal edge too
  for y in range(ys[1],ys[1]+3):
    for x in range(xs[0]+3,xs[1]-2):
      if g[y][x]==0: g[y][x]=color
print(json.dumps(g,separators=(',',':')))

